BEGIN;

DELETE FROM questions WHERE topic = 'The Nervous System' AND subtopic IN ('CNS Tissue Organization', 'Myelin & Myelinating Glia', 'Neuron Anatomy & Signal Flow', 'Support Glia: Astrocytes, Ependymal & Microglia', 'The Synapse & Synaptic Terminal');

-- Q1 [Neuron Anatomy & Signal Flow | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub1$Neuron Anatomy & Signal Flow$sub1$, $qt1$A histologist isolates the single region of a multipolar neuron that houses the nucleus together with the rough and smooth endoplasmic reticulum, Golgi apparatus, ribosomes, and mitochondria, and notes that this is where the cell carries out the bulk of its protein synthesis. Which part of the neuron has been isolated?$qt1$, $op1$[{"label": "A", "text": "The soma, because it contains the nucleus along with the rough and smooth endoplasmic reticulum, ribosomes, and Golgi apparatus needed for protein synthesis"}, {"label": "B", "text": "A dendrite, because the branched dendrites hold the nucleus and ribosomes that receive and translate incoming messages"}, {"label": "C", "text": "The axon hillock, because this tapering region stores the nucleus and Golgi that assemble secreted proteins"}, {"label": "D", "text": "The axon terminal, because the terminal swelling packages the nucleus and ribosomes that build neurotransmitter proteins"}]$op1$::jsonb, 'A', $ex1$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is A because the soma (cell body) is the only neuronal region that houses the nucleus together with the full complement of biosynthetic organelles, making it the cell's metabolic and protein-synthetic center. OpenStax Biology 2e states that "each neuron has a cell body (or soma) that contains a nucleus, smooth and rough endoplasmic reticulum, Golgi apparatus, mitochondria, and other cellular components," which is exactly the organelle inventory described in the scenario. The dendrites, axon hillock, and axon terminals are processes or specialized regions that branch off from the soma; they carry out reception, integration, and signal output, respectively, but do not house the nucleus or the bulk of the synthetic machinery. Because protein synthesis requires the nucleus, ER, ribosomes, and Golgi acting together, the region the histologist isolated must be the soma. (Choice A) Correct: the soma is the organelle-bearing cell body that contains the nucleus, smooth and rough ER, ribosomes, and Golgi, and is therefore the site of the neuron's protein synthesis. (Choice B) Incorrect: dendrites are tree-like structures that extend from the cell body to receive messages at synapses; they do not hold the nucleus. (Choice C) Incorrect: the axon hillock is a tapering of the cell body that integrates signals and contains axoplasm of limited components, not a nucleus-bearing organelle store. (Choice D) Incorrect: axon terminals are endings that release chemicals to communicate with other cells and do not house the nucleus or ribosomal machinery. This is a Knowledge of Scientific Concepts and Principles question because it tests direct recall of which subcellular components reside in the neuronal soma versus its processes.$ex1$, 'easy', '3A', $cc1$Neuron & Glial Cell Structure$cc1$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a1B$Attributing the soma's nucleus and organelles to dendrites because dendrites are the input structures$a1B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a1C$Assigning the nucleus and Golgi to the axon hillock, a real cell-body region that integrates signals but stores only axoplasm$a1C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a1D$Placing the nucleus and ribosomes in the axon terminal, a real release site that houses neither$a1D$ FROM q;

-- Q2 [Neuron Anatomy & Signal Flow | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub2$Neuron Anatomy & Signal Flow$sub2$, $qt2$A neuroscientist labels a single multipolar neuron and asks a student to identify the structure responsible for collecting incoming chemical signals from neighboring neurons at synapses and conveying them inward toward the cell body. Which structure should the student name?$qt2$, $op2$[{"label": "A", "text": "The axon, because this single fiber receives incoming messages from other neurons and conducts them inward to the soma"}, {"label": "B", "text": "The dendrites, because these branched extensions receive incoming messages from other neurons at synapses and carry them inward to the soma"}, {"label": "C", "text": "The myelin sheath, because this insulating wrap is the site where the neuron receives synaptic input from neighboring cells"}, {"label": "D", "text": "The synaptic end bulbs, because these terminal swellings receive incoming signals and relay them back toward the cell body"}]$op2$::jsonb, 'B', $ex2$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is B because dendrites are the receptive processes of the neuron: tree-like extensions that reach away from the soma to gather messages from other neurons at synapses and carry that input inward toward the cell body. OpenStax Biology 2e states that "Dendrites are tree-like structures that extend away from the cell body to receive messages from other neurons at specialized junctions called synapses," and that once a signal is received by the dendrite "it then travels passively to the cell body"; OpenStax A&P 2e likewise notes that dendrites "receive information from other neurons at specialized areas of contact called synapses," giving the neuron its input-to-output polarity. The other choices name real neuronal structures but each carries the wrong directional or functional role. (Choice A) The axon is incorrect because it is the output fiber that "emerges from the cell body and projects to target cells," propagating the impulse away from the soma rather than gathering input. (Choice B) The dendrites are correct because they are the branched, spine-bearing receptive surfaces that take in synaptic signals and conduct them toward the cell body. (Choice C) The myelin sheath is incorrect because it is glial-made insulation that minimizes signal dissipation along the axon, not a site of synaptic reception. (Choice D) The synaptic end bulbs are incorrect because they sit at the end of the axon and make the output connection that releases transmitter onto the target cell, not an inward-conducting input. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the defined, signal-receiving role of the dendrite within standard neuron anatomy.$ex2$, 'easy', '3A', $cc2$Neuron & Glial Cell Structure$cc2$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a2A$input/output direction swapped — assigning the axon's outward-propagating role the receptive function of the dendrite$a2A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a2C$confusing glial insulation (myelin) with a neuronal receptive surface$a2C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a2D$treating an output terminal (synaptic end bulb) as an inward-conducting input site$a2D$ FROM q;

-- Q3 [Neuron Anatomy & Signal Flow | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub3$Neuron Anatomy & Signal Flow$sub3$, $qt3$A neurobiologist maps a single multipolar neuron and locates the one region where the signals arriving from many separate synapses are pooled together at the point where the cell body tapers into the outgoing fiber, and where the cell's single outgoing impulse first begins. Which structure has the neurobiologist identified?$qt3$, $op3$[{"label": "A", "text": "A dendritic spine, because these protrusions pool the converging inputs and launch the integrated outgoing signal toward the axon"}, {"label": "B", "text": "A node of Ranvier, because this gap collects the converging synaptic inputs and initiates the signal that travels down the axon"}, {"label": "C", "text": "The axon hillock, because it integrates signals arriving from multiple synapses and serves as the junction between the cell body and the axon where the outgoing signal begins"}, {"label": "D", "text": "The synaptic cleft, because this junction sums the inputs from many neurons and serves as the launch point for the outgoing impulse"}]$op3$::jsonb, 'C', $ex3$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is C because the axon hillock is the specialized region of the cell body that integrates signals from multiple synapses and forms the junction between the soma and the axon where the outgoing impulse is launched. OpenStax Biology 2e states that "The cell body contains a specialized structure, the axon hillock that integrates signals from multiple synapses and serves as a junction between the cell body and an axon," after which the axon propagates that integrated signal toward the axon terminals. OpenStax A&P 2e confirms this is the launch point, noting that "Action potentials are generated in the trigger zone, which is a combination of the axon hillock and initial segment." The scenario describes exactly these two defining features—pooling of many synaptic inputs and the soma-to-axon transition where the single output starts—so the structure must be the axon hillock. (Choice A) A dendritic spine is a protrusion that increases receptive surface area for synaptic connections at the input end, not the site that integrates inputs or launches the impulse. (Choice B) A node of Ranvier is a periodic gap in the myelin sheath where an already-traveling signal is "recharged" as it moves down the axon, not the integrating origin of the impulse. (Choice C) The axon hillock integrates inputs from multiple synapses and sits at the cell-body-to-axon junction where the outgoing signal begins, matching the scenario. (Choice D) The synaptic cleft is the extracellular gap at the area of contact where dendrites receive input, not an intracellular region that sums signals or launches an impulse. This is a Scientific Reasoning and Problem Solving question because it requires inferring the identity of an unnamed structure from a functional description of input integration and output initiation rather than recalling the term directly.$ex3$, 'medium', '3A', $cc3$Neuron & Glial Cell Structure$cc3$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a3A$Assigning the integrate-and-launch role to the input-end dendritic spine, which only increases receptive surface area$a3A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a3B$Confusing the impulse-recharging node of Ranvier with the impulse-originating hillock$a3B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a3D$Treating the extracellular synaptic cleft as an intracellular integrating/launch region$a3D$ FROM q;

-- Q4 [Neuron Anatomy & Signal Flow | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub4$Neuron Anatomy & Signal Flow$sub4$, $qt4$A researcher applies a localized conduction block at the midpoint of a single neuron's axon, leaving the dendrites, soma, and axon terminal otherwise structurally intact. A normal excitatory input then arrives at the neuron's dendrites. Which prediction correctly describes how far the signal travels?$qt4$, $op4$[{"label": "A", "text": "The signal reaches the axon terminal but fails to reach the dendrites and soma, because impulses begin at the terminal and travel back toward the cell body."}, {"label": "B", "text": "The signal bypasses the block entirely because the dendrites hand the impulse directly to the axon terminal without passing through the cell body."}, {"label": "C", "text": "The signal reaches the dendrites, soma, and axon but stalls just before the dendrites, because input is received at the terminal end of the cell."}, {"label": "D", "text": "The signal reaches the dendrites and soma but fails to travel down the axon to the terminal, because information flows one way from dendrites, across the cell body, and down the axon."}]$op4$::jsonb, 'D', $ex4$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is D because a neuron is polarized: information enters at the dendrites, passes across the soma, and only then travels down the axon to the terminal, so a block at the axon's midpoint stops the signal there. The dendrites receive the input and pass it passively to the cell body, which sits upstream of the block, so those compartments are still reached; the axon terminal lies downstream of the midpoint block, so the impulse cannot arrive there. Because the flow direction is fixed (dendrites → soma → axon → terminal), the student must trace the lesion's position along that ordering rather than simply name a part. (Choice A) is reversed: the cell does not initiate at the terminal and travel back to the soma; flow runs from the dendrites across the cell body and down the axon, so the dendrites and soma are reached and the terminal is not. (Choice B) is wrong because there is no dendrite-to-terminal shortcut; the signal must cross the soma, so it cannot bypass an axonal block. (Choice C) misorders the same parts by treating the terminal as the receiving end, but reception occurs at the dendrites, and an upstream block does not stall the signal "just before the dendrites." (Choice D) is correct because the dendrites and soma lie upstream of the axonal block and are reached, while the terminal lies downstream and is not, consistent with the neuron's one-way polarity. This is a Scientific Reasoning and Problem Solving question because it requires applying the fixed dendrite-to-soma-to-axon-to-terminal flow rule to a lesion scenario and predicting which downstream compartments lose the signal.$ex4$, 'medium', '3A', $cc4$Neuron & Glial Cell Structure$cc4$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a4A$Reverses the direction of neuronal information flow so the impulse starts at the terminal and travels back to the soma.$a4A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a4B$Invents a dendrite-to-terminal shortcut that skips the cell body, ignoring that flow must cross the soma.$a4B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a4C$Conflates the receiving end (dendrites) with the output end (terminal), misordering the same compartments.$a4C$ FROM q;

-- Q5 [Neuron Anatomy & Signal Flow | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub5$Neuron Anatomy & Signal Flow$sub5$, $qt5$A multipolar CNS neuron simultaneously receives a powerful excitatory input on one dendritic branch and several inhibitory inputs distributed across its soma and other dendrites; when the inputs are summed, the membrane at the trigger zone reaches only \(-58\) mV, just short of the \(-55\) mV threshold. A researcher asks whether the neuron fires and what determines the outcome. Which prediction is correct?$qt5$, $op5$[{"label": "A", "text": "No impulse is initiated, because the axon hillock integrates all converging inputs and the inhibitory inputs offset the excitatory one, so the net summed signal fails to reach threshold at the trigger zone."}, {"label": "B", "text": "An impulse is initiated, because any single excitatory synapse that depolarizes its dendrite is sufficient on its own to fire the axon regardless of the inhibitory inputs."}, {"label": "C", "text": "An impulse is initiated at the dendrite itself, because the dendrite receiving the strongest excitatory input integrates the inputs and launches the signal locally."}, {"label": "D", "text": "No impulse is initiated, because the inhibitory inputs physically block conduction at the nodes of Ranvier farther down the axon after the impulse has already left the hillock."}]$op5$::jsonb, 'A', $ex5$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is A because the axon hillock is the single site that integrates every excitatory and inhibitory signal converging on the dendrites and soma, and an action potential is launched only if their net sum drives the trigger zone to threshold. Biology 2e states that the axon hillock "integrates signals from multiple synapses," and that Na+ channels in the axon hillock open only once the membrane is depolarized to its threshold potential (-55 mV); since the summed inhibitory inputs here offset the strong excitatory input and leave the membrane at -58 mV, threshold is not reached and no impulse fires. A&P 2e adds that action potentials are generated in the trigger zone formed by the axon hillock and initial segment, confirming this is where the net decision is made. (Choice A) is correct because integration of the net summed signal at the trigger zone determines firing, and a net subthreshold sum produces no action potential. (Choice B) is wrong because, although excitatory inputs do depolarize, firing depends on the NET summed signal reaching threshold, not on any one input acting alone. (Choice C) is wrong because dendrites receive and passively conduct signals to the cell body but do not integrate-and-launch; that role belongs to the axon hillock. (Choice D) is wrong because nodes of Ranvier merely recharge a signal that is already propagating down the axon; they do not host the integration/veto decision, which occurs upstream at the trigger zone. This is a Scientific Reasoning and Problem Solving question because it requires applying the integration and net-summation-to-threshold mechanism to a specific scenario of competing inputs to predict the outcome and locate where the decision is made.$ex5$, 'hard', '3A', $cc5$Neuron & Glial Cell Structure$cc5$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a5B$Excitatory inputs do depolarize, but firing requires the net summed signal to reach threshold rather than any single input alone — a 510-tempting trap.$a5B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a5C$Misassigns the integrate-and-launch role to the dendrite when it belongs to the axon hillock/trigger zone.$a5C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a5D$Misplaces the integration/veto decision to a downstream recharge site (nodes of Ranvier) after the trigger zone.$a5D$ FROM q;

-- Q6 [Myelin & Myelinating Glia | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub6$Myelin & Myelinating Glia$sub6$, $qt6$A neuroscientist labels the glial cells whose membrane processes wrap multiple axon segments in myelin within the white matter of the spinal cord. Which glial cell type is being labeled?$qt6$, $op6$[{"label": "A", "text": "The Schwann cell, which wraps a single segment of one axon in myelin"}, {"label": "B", "text": "The oligodendrocyte, which extends processes that wrap multiple axon segments in myelin"}, {"label": "C", "text": "The astrocyte, which supplies nutrients and ions and forms the blood-brain barrier"}, {"label": "D", "text": "The microglial cell, which scavenges and degrades dead cells and pathogens"}]$op6$::jsonb, 'B', $ex6$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is B because the oligodendrocyte is the CNS glial cell that insulates axons in myelin, and the spinal cord white matter is part of the central nervous system. OpenStax Anatomy & Physiology states that "Also found in CNS tissue is the oligodendrocyte... Each one reaches out and surrounds an axon to insulate it in myelin. One oligodendrocyte will provide the myelin for multiple axon segments," and OpenStax Biology confirms that "Oligodendrocytes... form myelin sheaths around axons in the CNS." This single oligodendrocyte-to-many-segments arrangement is exactly what the scenario describes, distinguishing it from the PNS Schwann cell, which wraps only one segment. (Choice A) The Schwann cell is a real myelinating glial cell, but it "insulate axons with myelin in the periphery" (PNS), not in the spinal cord, and it surrounds only one axon segment. (Choice B) is correct because the oligodendrocyte is the CNS glial cell whose few branching processes each wrap an axon segment in myelin, servicing multiple segments at once. (Choice C) The astrocyte is a genuine CNS glial cell, but it "provide nutrients and other substances to neurons, regulate the concentrations of ions... and provide structural support," and it forms the blood-brain barrier rather than producing myelin. (Choice D) The microglial cell is a real CNS glial cell, but it "scavenge and degrade dead cells and protect the brain from invading microorganisms," performing immune functions rather than myelination. This is a Knowledge of Scientific Concepts and Principles question because it requires directly identifying the glial cell type responsible for CNS myelination from its known structure and function.$ex6$, 'easy', '3A', $cc6$Neuron & Glial Cell Structure$cc6$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a6A$Correct myelinating glia for the wrong nervous-system division (PNS Schwann cell instead of CNS oligodendrocyte)$a6A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a6C$Real CNS glial cell assigned myelination when its true role is nutrient/ion support and blood-brain barrier formation$a6C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a6D$Real CNS glial cell assigned myelination when its true role is phagocytic immune surveillance$a6D$ FROM q;

-- Q7 [Myelin & Myelinating Glia | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub7$Myelin & Myelinating Glia$sub7$, $qt7$A histologist examines central nervous tissue and finds a single glial cell whose several processes each reach out and wrap a different axon segment in myelin, insulating multiple separate segments at the same time. The investigator is asked to identify this cell and its location.$qt7$, $op7$[{"label": "A", "text": "A Schwann cell in the PNS"}, {"label": "B", "text": "A satellite cell in the PNS"}, {"label": "C", "text": "An oligodendrocyte in the CNS"}, {"label": "D", "text": "An astrocyte in the CNS"}]$op7$::jsonb, 'C', $ex7$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is C because the only myelinating glial cell that uses several processes to insulate multiple separate axon segments at once resides in the CNS and is the oligodendrocyte. The text states that an oligodendrocyte has "a few processes that extend from the cell body... One oligodendrocyte will provide the myelin for multiple axon segments, either for the same axon or for separate axons" (A&P 21503-21505), and that "one oligodendrocyte can provide myelin for multiple neurons" (Bio 45838-45839). The described behavior—one cell, many processes, many segments, in CNS tissue—matches the oligodendrocyte uniquely and rules out the single-segment PNS myelinator and the non-myelinating glia. (Choice A) A Schwann cell does make myelin, but it does so in the PNS and "wraps around a portion of only one axon segment and no others," so it cannot insulate multiple separate segments at once (A&P 21541-21543). (Choice B) A satellite cell is a real PNS glial cell, but it surrounds the cell bodies of neurons in ganglia to provide support and does not make myelin at all (A&P 21535-21538). (Choice C) An oligodendrocyte is correct because its multiple processes each myelinate a different axon segment in the CNS, exactly as observed. (Choice D) An astrocyte is a CNS glial cell with many processes, but those processes contact capillaries and neurons to provide nutrients, support synapses, and form the blood-brain barrier rather than wrapping axons in myelin (Bio 45831-45833). This is a Scientific Reasoning and Problem Solving question because it requires using observed structural and functional features (one cell, multiple processes, multiple myelinated segments, CNS location) to infer the specific glial cell identity and distinguish it from other real glia.$ex7$, 'medium', '3A', $cc7$Neuron & Glial Cell Structure$cc7$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a7A$Right that it myelinates, but assigns the multi-segment role to the PNS Schwann cell, which actually myelinates only a single segment$a7A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a7B$Names a real PNS glial cell but wrongly attributes a myelinating function to a cell that only supports ganglionic cell bodies$a7B$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a7D$A real multi-process CNS glial cell, but its processes support synapses and the BBB rather than form myelin$a7D$ FROM q;

-- Q8 [Myelin & Myelinating Glia | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub8$Myelin & Myelinating Glia$sub8$, $qt8$A neurologist studies a patient whose immune system has stripped the myelin from a stretch of axons in the central nervous system, leaving those segments bare. Compared with the same axons before the myelin was lost, the neurologist predicts that an action potential traveling down a demyelinated segment will do which of the following?$qt8$, $op8$[{"label": "A", "text": "Travel faster, because removing the insulating layer lets ions cross the axon membrane more freely along its length."}, {"label": "B", "text": "Fail entirely, because the myelin sheath is the structure that generates the electrical impulse in the first place."}, {"label": "C", "text": "Travel at an unchanged speed, because the nodes of Ranvier already leave the axon membrane partly exposed."}, {"label": "D", "text": "Travel more slowly, because current now leaks out of the previously insulated axon membrane and dissipates."}]$op8$::jsonb, 'D', $ex8$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is D because myelin normally acts as an insulator that prevents current from leaving the axon, so stripping it away lets current leak out and dissipate, slowing conduction. The Biology text states that "Myelin acts as an insulator that prevents current from leaving the axon; this increases the speed of action potential conduction. In demyelinating diseases like multiple sclerosis, action potential conduction slows because current leaks from previously insulated axon areas" (Bio 46036-46038). The Anatomy & Physiology text reinforces that when the myelin insulation is compromised, the result is "making electrical signaling slower" (A&P 21591/21601). Because the question asks you to take myelin's insulating role and predict the downstream consequence of removing it, the slowing of conduction is the keyed outcome. (Choice A) is wrong because it reverses the relationship: insulation speeds conduction by keeping current in, so letting ions cross more freely slows the signal rather than speeding it. (Choice B) is wrong because the neuron, not the myelin sheath, generates the impulse — myelin "is not actually part of the neuron" and only insulates it (Bio 45708-45709; A&P 21369-21370). (Choice C) is a partial truth: the nodes of Ranvier are real gaps in the sheath (Bio 46039-46040; A&P 21371-21372), but the long insulated segments between nodes still matter, so demyelinating those segments does slow conduction. (Choice D) is correct because losing the insulation lets current leak from previously insulated areas, dissipating the signal and slowing it. This is a Scientific Reasoning and Problem Solving question because it requires applying myelin's known insulating function to a novel demyelination scenario and predicting the functional consequence for signal transmission rather than recalling a stated fact.$ex8$, 'medium', '3A', $cc8$Neuron & Glial Cell Structure$cc8$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a8A$Inverting myelin's insulating role so that removing it is imagined to speed conduction instead of slowing it$a8A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a8B$Treating the myelin sheath as the impulse generator rather than the neuron, so demyelination is thought to abolish the signal$a8B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a8C$Citing the real exposed nodes of Ranvier to wrongly conclude that demyelinating the insulated segments leaves conduction speed unchanged$a8C$ FROM q;

-- Q9 [Myelin & Myelinating Glia | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub9$Myelin & Myelinating Glia$sub9$, $qt9$A geneticist studies an animal carrying a mutation that disrupts the development of one glial lineage, and finds that peripheral nerve axons fail to acquire a myelin sheath while axons in the brain and spinal cord remain fully myelinated. The geneticist concludes that a single, location-specific myelinating cell type is selectively impaired by the mutation.$qt9$, $op9$[{"label": "A", "text": "Schwann cells are impaired, so PNS axons go unmyelinated, while CNS axons stay myelinated because oligodendrocytes make central myelin."}, {"label": "B", "text": "Oligodendrocytes are impaired, so CNS axons go unmyelinated, while PNS axons stay myelinated because Schwann cells make peripheral myelin."}, {"label": "C", "text": "Satellite cells are impaired, so PNS axons go unmyelinated, while CNS axons stay myelinated because oligodendrocytes make central myelin."}, {"label": "D", "text": "Astrocytes are impaired, so PNS axons go unmyelinated, while CNS axons stay myelinated because oligodendrocytes make central myelin."}]$op9$::jsonb, 'A', $ex9$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is A because the only glial cell that myelinates axons in the peripheral nervous system is the Schwann cell, so a defect that strips PNS axons of myelin while sparing the brain and spinal cord must lie in the Schwann-cell lineage. The text states the Schwann cell is the PNS glial cell that "insulate axons with myelin in the periphery," whereas the oligodendrocyte "is the glial cell type that insulates axons in the CNS"; because two distinct cell types build the two myelin pools, impairing one leaves the other intact. This is exactly the observed pattern: bare peripheral axons but fully myelinated central axons, which points to Schwann cells, not the central myelinator. (Choice A) is correct: Schwann cells myelinate the PNS, so their selective loss leaves PNS axons bare while oligodendrocyte-made CNS myelin persists. (Choice B) reverses the locations — oligodendrocyte impairment would leave CNS axons bare and PNS axons normal, the opposite of what is seen. (Choice C) is wrong because satellite cells merely surround PNS ganglion cell bodies for support and never form myelin, so they cannot be the failed myelinating cell. (Choice D) is wrong because astrocytes are CNS glia that form the blood-brain barrier rather than myelinate peripheral axons. This is a Scientific Reasoning and Problem Solving question because it requires mapping an observed lesion pattern (PNS-only demyelination) back to the specific cell lineage whose location-restricted function explains the data.$ex9$, 'hard', '3A', $cc9$Neuron & Glial Cell Structure$cc9$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a9B$Swaps the CNS and PNS myelinating cell types so the impaired cell and the spared location are inverted relative to the observed data.$a9B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a9C$Names the other real PNS glial cell (satellite cell) as a myelinator, when it only provides support to ganglion cell bodies.$a9C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a9D$Names a genuine glial cell (astrocyte) but assigns it a peripheral myelinating role it never has, since it is a CNS blood-brain-barrier cell.$a9D$ FROM q;

-- Q10 [Myelin & Myelinating Glia | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub10$Myelin & Myelinating Glia$sub10$, $qt10$A researcher isolates a purified myelin membrane fraction from peripheral nerve and a plasma-membrane fraction from a non-glial cell, then analyzes each for its relative content of lipid, protein, nucleic acid, and carbohydrate. Compared with the non-glial membrane, the myelin fraction is predicted to show which compositional difference?$qt10$, $op10$[{"label": "A", "text": "It is far richer in protein than in lipid because dense protein layers are what hold the wrapped sheath together."}, {"label": "B", "text": "It is far richer in lipid than a typical membrane because the sheath is the glial cell's phospholipid plasma membrane wrapped repeatedly around the axon."}, {"label": "C", "text": "It is rich in nucleic acid because the sheath carries the glial cell's nucleus woven within its wraps."}, {"label": "D", "text": "It is rich in carbohydrate because the sheath is built from the polysaccharide ground substance secreted around the axon."}]$op10$::jsonb, 'B', $ex10$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is B because myelin is essentially the phospholipid plasma membrane of a glial cell (a Schwann cell in the PNS) wrapped many times around the axon, so its molecular composition is dominated by membrane lipid. The text states that "Myelin is a lipid-rich sheath that surrounds the axon" and that "The lipids are essentially the phospholipids of the glial cell membrane" (A&P), and quantifies this by noting myelin "contains only 18 percent protein and 76 percent lipid," far more lipid than a typical human cell membrane at about 40 percent lipid (Bio). Because the wrap is layer upon layer of plasma membrane with little intervening cytoplasm, a purified myelin fraction is predicted to be enriched in lipid relative to a non-glial membrane. (Choice A) is a partial truth: integral proteins do help "hold the layers of the glial cell membrane closely together," but at only 18 percent protein versus 76 percent lipid, myelin is overwhelmingly lipid, not protein. (Choice B) is correct because the sheath is repeatedly wrapped glial phospholipid membrane, making it lipid-rich. (Choice C) is wrong because in a Schwann cell the nucleus and cytoplasm sit "as a bulge on one side of the myelin sheath," not woven through the lipid wraps, so the sheath itself is not nucleic-acid-rich. (Choice D) is wrong because myelin is glial membrane lipid, not an extracellular polysaccharide ground substance secreted around the axon. This is a Scientific Reasoning and Problem Solving question because it requires reasoning from myelin's structural origin as wrapped glial plasma membrane to predict the outcome of a compositional comparison against a non-glial membrane.$ex10$, 'hard', '3A', $cc10$Neuron & Glial Cell Structure$cc10$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a10A$Integral proteins really do bind the membrane layers together, but myelin is ~76% lipid vs 18% protein, so 'far richer in protein' inverts the dominant component.$a10A$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a10C$Confuses where the Schwann cell nucleus sits (an outer cytoplasmic bulge beside the sheath) with the composition of the wrapped lipid layers themselves.$a10C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a10D$Mistakes myelin (wrapped glial phospholipid membrane) for an extracellular polysaccharide ground-substance matrix.$a10D$ FROM q;

-- Q11 [The Synapse & Synaptic Terminal | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub11$The Synapse & Synaptic Terminal$sub11$, $qt11$A neuron's signal travels to the very end of one of its axon branches, where the branch tip swells into a small enlargement that physically contacts the target cell and releases neurotransmitter across the synapse. This terminal swelling is best identified as the:$qt11$, $op11$[{"label": "A", "text": "node of Ranvier, a gap in the myelin sheath spaced along the length of the axon"}, {"label": "B", "text": "axon hillock, the cone-shaped region where the cell body gives rise to the axon"}, {"label": "C", "text": "synaptic end bulb, the enlargement at the tip of an axon branch that contacts the target cell"}, {"label": "D", "text": "dendritic spine, a small protrusion that increases surface area for incoming synaptic input"}]$op11$::jsonb, 'C', $ex11$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is C because the swollen structure at the very end of an axon branch that forms the presynaptic side of the synapse is the synaptic end bulb. OpenStax Anatomy & Physiology 2e states that "At the end of the axon is the axon terminal, where there are usually several branches extending toward the target cell, each of which ends in an enlargement called a synaptic end bulb," and that "These bulbs are what make the connection with the target cell at the synapse." The glossary further defines the synaptic end bulb as the "swelling at the end of an axon where neurotransmitter molecules are released onto a target cell across a synapse," which matches the described scenario exactly. The other structures named are real but are located elsewhere on the neuron and do not form the presynaptic terminal. (Choice A) The node of Ranvier is a gap in the myelin covering spaced along the axon's length, not a swelling at the axon's terminal tip. (Choice B) The axon hillock is the cone-shaped junction where the cell body meets the axon, at the signal-integrating origin of the axon rather than its end. (Choice C) The synaptic end bulb is correct because it is the enlargement at the tip of an axon branch that contacts the target cell and releases neurotransmitter across the synapse. (Choice D) The dendritic spine is a protrusion on the receiving (postsynaptic) cell that increases surface area for synaptic input, not the presynaptic axon terminal. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling and identifying the defined name and location of a specific neuronal structure described in the textbook.$ex11$, 'easy', '3A', $cc11$Neuron & Glial Cell Structure$cc11$, 'biology', 1, 70
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a11A$Real axonal structure located along the axon rather than at its terminal end$a11A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a11B$Real neuron structure at the opposite, signal-integrating origin of the axon$a11B$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a11D$Real synaptic structure on the postsynaptic receiving cell, not the presynaptic axon terminal$a11D$ FROM q;

-- Q12 [The Synapse & Synaptic Terminal | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub12$The Synapse & Synaptic Terminal$sub12$, $qt12$At a chemical synapse in the central nervous system, an action potential triggers \(\text{Ca}^{2+}\) influx into the presynaptic terminal of a neuron that is not cytoplasmically continuous with its target. A student is asked to trace how a single neurotransmitter molecule travels from the presynaptic terminal to influence the postsynaptic neuron. Which route does the neurotransmitter follow?$qt12$, $op12$[{"label": "A", "text": "It moves directly from the presynaptic cytoplasm into the postsynaptic cytoplasm through channel proteins that physically link the two cells."}, {"label": "B", "text": "It crosses the cleft as an electrical current carried by ions flowing between the directly touching presynaptic and postsynaptic membranes."}, {"label": "C", "text": "It is pumped back into the presynaptic terminal by reuptake transporters before it can reach the postsynaptic membrane."}, {"label": "D", "text": "It is released by exocytosis into the synaptic cleft and diffuses across that extracellular gap to receptors on the separate postsynaptic membrane."}]$op12$::jsonb, 'D', $ex12$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is D because at a chemical synapse the two neurons are separated by the synaptic cleft, an extracellular gap, so the signal cannot flow through shared cytoplasm and must instead be released and diffuse across the gap. OpenStax Anatomy & Physiology 2e states that "the neurotransmitter is released through exocytosis into the small gap between the cells, known as the synaptic cleft," and that "Once in the synaptic cleft, the neurotransmitter diffuses the short distance to the postsynaptic membrane and can interact with neurotransmitter receptors." OpenStax Biology 2e likewise describes the synaptic cleft as "the extracellular space between the presynaptic and postsynaptic membranes," across which "The neurotransmitter diffuses... and binds to receptor proteins on the postsynaptic membrane." Because the presynaptic and postsynaptic cells are not cytoplasmically joined, exocytosis followed by diffusion across the extracellular cleft is the only viable route. (Choice A) describes the direct cytoplasmic connection of an electrical synapse, where "there is a direct connection between the two cells so that ions can pass directly from one cell to the next," not the chemical-synapse route in question. (Choice B) also describes the electrical-synapse mechanism in which depolarization spreads as ions "pass between the cells," substituting an electrical current for the chemical release-and-diffusion process. (Choice C) names reuptake, a later clearance step in which "A pump in the cell membrane of the presynaptic element... will clear the amino acid from the synaptic cleft," not the path from release to the postsynaptic receptor. (Choice D) correctly captures exocytotic release into the cleft followed by diffusion across the extracellular gap to postsynaptic receptors. This is a Scientific Reasoning and Problem Solving question because it requires predicting the only physically possible signaling route from the structural fact that the two cells are separated by extracellular space rather than joined cytoplasm.$ex12$, 'medium', '3A', $cc12$Neuron & Glial Cell Structure$cc12$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a12A$Describes an electrical synapse / gap junction (direct cytoplasmic channel coupling) instead of the chemical-synapse cleft.$a12A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a12B$Swaps the chemical release-and-diffusion mechanism for the electrical-synapse mechanism of ionic current across touching membranes.$a12B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a12C$Confuses the later reuptake/clearance step with the route from release to the postsynaptic receptor.$a12C$ FROM q;

-- Q13 [The Synapse & Synaptic Terminal | medium | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub13$The Synapse & Synaptic Terminal$sub13$, $qt13$A neurophysiologist diagrams a chemical synapse between two neurons and labels four membranes: the axon-terminal membrane of the signaling cell, the gap fluid between the cells, a myelinated stretch of the signaling axon just upstream of the terminal, and the receptor-bearing membrane of the cell on the far side of the cleft. To mark the postsynaptic element, which membrane does she select?$qt13$, $op13$[{"label": "A", "text": "The receptor-bearing membrane of the target cell across the cleft"}, {"label": "B", "text": "The axon-terminal membrane of the signaling neuron that fuses with vesicles"}, {"label": "C", "text": "The extracellular gap between the two cells where neurotransmitter diffuses"}, {"label": "D", "text": "The myelin-wrapped segment of the signaling axon just before the terminal"}]$op13$::jsonb, 'A', $ex13$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is A because the postsynaptic element is the membrane of the cell receiving the signal, located on the opposite side of the cleft and bearing the neurotransmitter receptors. Across a chemical synapse the signaling (presynaptic) neuron releases neurotransmitter from its axon terminal; the chemical then diffuses across the synaptic cleft and binds receptor proteins on the postsynaptic membrane of the target cell. Because the question asks for the receiving membrane, the only structure that both lies across the cleft and carries the receptors is the target cell's membrane, distinguishing it from the sending terminal, the gap itself, and any upstream axonal segment. (Choice A) is correct: the neurotransmitter "diffuses across the synaptic cleft and binds to receptor proteins on the postsynaptic membrane," which is the membrane of the receiving cell. (Choice B) is the presynaptic element, the sending side where vesicles fuse and release neurotransmitter, not the receiving side. (Choice C) is the synaptic cleft, the extracellular space where neurotransmitter diffuses, not a postsynaptic membrane. (Choice D) is a myelinated portion of the presynaptic axon that lies upstream of the terminal and outside the synapse, so it is not the postsynaptic element. This is a Scientific Reasoning and Problem Solving question because it requires applying the defined roles of synaptic components to a labeled scenario and reasoning out which specific membrane satisfies the postsynaptic criteria of being the receiving cell's receptor-bearing membrane across the cleft.$ex13$, 'medium', '3A', $cc13$Neuron & Glial Cell Structure$cc13$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a13B$Swapping the sending (presynaptic) and receiving (postsynaptic) sides of the synapse$a13B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a13C$Confusing the synaptic cleft (a space) with the postsynaptic membrane (a structure)$a13C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a13D$Naming a real axonal structure of the presynaptic neuron that lies outside the synapse$a13D$ FROM q;

-- Q14 [The Synapse & Synaptic Terminal | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub14$The Synapse & Synaptic Terminal$sub14$, $qt14$A researcher microinjects a small fluorescent dye into one neuron and, within seconds and without releasing the dye into the surrounding medium, observes the dye appear in the cytoplasm of a second neuron that is in direct contact with the first. From this result, the junction between the two neurons is best identified as which type, and why?$qt14$, $op14$[{"label": "A", "text": "A chemical synapse, because neurotransmitter released into the cleft carries the dye across to the second neuron"}, {"label": "B", "text": "An electrical synapse, because gap-junction channel proteins physically join the two membranes and let small molecules pass directly between the cytoplasms"}, {"label": "C", "text": "A chemical synapse, because the dye diffuses across the 20-40 nm synaptic cleft together with the neurotransmitter"}, {"label": "D", "text": "An electrical synapse, because synaptic vesicles fuse with the presynaptic membrane and inject the dye into the second neuron"}]$op14$::jsonb, 'B', $ex14$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is B because direct, second-by-second cytoplasm-to-cytoplasm transfer of a small molecule is the structural hallmark of an electrical synapse, whose membranes are physically joined by gap-junction channels. OpenStax Biology 2e states that in an electrical synapse "the presynaptic and postsynaptic membranes are very close together and are actually physically connected by channel proteins forming gap junctions," and that besides ions "other molecules, such as ATP, can diffuse through the large gap junction pores," so a small injected dye would likewise pass straight into the joined cell (lines 46140-46143). OpenStax A&P 2e similarly notes that "in an electrical synapse, there is a direct connection between the two cells so that ions can pass directly from one cell to the next" (lines 22202-22203). A chemical synapse cannot produce this result because its cells are separated by the synaptic cleft, "the extracellular space between the presynaptic and postsynaptic membranes," across which only released neurotransmitter—not cytoplasmic contents—diffuses (lines 46080-46082). (Choice A) is wrong because neurotransmitter is secreted into an extracellular cleft and binds surface receptors; it never carries cytoplasmic dye into the next cell's interior. (Choice B) is correct because gap-junction channels create a continuous cytoplasmic pathway that allows the small dye, like ions and ATP, to move directly between the two neurons. (Choice C) is wrong because the 20-40 nm cleft is exactly the extracellular barrier that would prevent direct cytoplasm-to-cytoplasm dye transfer, even though the cleft and diffusion are genuine features of a chemical synapse. (Choice D) is wrong because vesicle fusion and exocytosis are steps of chemical, not electrical, transmission, and electrical synapses lack this vesicular release machinery. This is a Scientific Reasoning and Problem Solving question because it requires interpreting an experimental observation (direct dye passage) and reasoning back to the underlying junctional structure that could permit it, rather than recalling a stated fact.$ex14$, 'hard', '3A', $cc14$Neuron & Glial Cell Structure$cc14$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a14A$Believing neurotransmitter release carries cytoplasmic contents (a dye) across a chemical synapse, ignoring that the cells are separated by an extracellular cleft$a14A$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a14C$Correctly cites the real 20-40 nm cleft and diffusion of a chemical synapse but misapplies it—the cleft is exactly what blocks direct cytoplasm-to-cytoplasm transfer$a14C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a14D$Attributes vesicle fusion/exocytosis (a chemical-synapse step) to an electrical synapse, which lacks vesicular release$a14D$ FROM q;

-- Q15 [The Synapse & Synaptic Terminal | hard | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub15$The Synapse & Synaptic Terminal$sub15$, $qt15$A pharmacologist maps a single chemical synapse and finds neurotransmitter-filled vesicles concentrated in one of the two apposed membranes and ligand-gated receptor proteins concentrated in the other. From this architecture, the pharmacologist predicts that an electrical signal arriving at this synapse can be chemically relayed in only one direction. Which arrangement of vesicles and receptors accounts for that one-way relay?$qt15$, $op15$[{"label": "A", "text": "Vesicles sit in the postsynaptic membrane and release transmitter back across the cleft toward the axon terminal, which carries the receptors."}, {"label": "B", "text": "The postsynaptic membrane both binds transmitter at its receptors and stores transmitter in vesicles that it releases across the cleft."}, {"label": "C", "text": "Vesicles are clustered in the presynaptic axon terminal and the postsynaptic membrane bears only receptors, so transmitter crosses the cleft one way."}, {"label": "D", "text": "Vesicles are split evenly between the two membranes, letting either side release transmitter and pass the signal across the cleft in either direction."}]$op15$::jsonb, 'C', $ex15$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is C because the neurotransmitter-containing vesicles are confined to the presynaptic axon terminal, while the postsynaptic membrane carries only receptor proteins, so transmitter can be released from just one side and the synapse relays the signal in a single direction across the cleft. OpenStax A&P 2e lists the common parts of a chemical synapse as a presynaptic element, "neurotransmitter (packaged in vesicles)," a synaptic cleft, receptor proteins, and a postsynaptic element, and states that "the presynaptic element is the motor neuron's axon terminals" while the receptor protein and postsynaptic element are on the receiving cell; Ca2+ entry "facilitates the merging of the vesicle with the presynaptic membrane so that the neurotransmitter is released through exocytosis... into the... synaptic cleft." OpenStax Biology 2e adds that neurotransmitters are released "from the presynaptic cell (the cell emitting the signal)" and then "binds the receptor on the surface of the postsynaptic cell," confirming that release is a presynaptic event and reception a postsynaptic one. Because only the presynaptic terminal holds vesicles, transmitter can only flow toward the receptor-bearing postsynaptic membrane, which is what makes chemical transmission unidirectional. (Choice A) is incorrect because it reverses the sending and receiving sides: the vesicles are presynaptic (in the axon terminal) and the receptors are postsynaptic, not the other way around. (Choice B) is incorrect because, although the postsynaptic membrane truly does bear receptors, carrying receptors does not mean it stores or releases transmitter vesicles, which remain in the presynaptic terminal. (Choice C) is correct because vesicles are clustered in the presynaptic axon terminal and the postsynaptic membrane bears only receptors, restricting release to one side and transmission to one direction. (Choice D) is incorrect because vesicles are confined to the presynaptic terminal rather than split between membranes, and that confinement is precisely what prevents the synapse from passing transmitter in either direction. This is a Scientific Reasoning and Problem Solving question because it requires the test-taker to reason from the spatial architecture of the synapse to a functional prediction about the direction of signal transmission, rather than simply recalling where vesicles are located.$ex15$, 'hard', '3A', $cc15$Neuron & Glial Cell Structure$cc15$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a15A$Swaps the presynaptic (vesicle-bearing) and postsynaptic (receptor-bearing) sides$a15A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a15B$Correctly places receptors on the postsynaptic membrane but wrongly infers it also stores and releases vesicles$a15B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a15D$Assumes vesicles are distributed on both membranes, making transmission bidirectional$a15D$ FROM q;

-- Q16 [Support Glia: Astrocytes, Ependymal & Microglia | easy | Skill 1 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub16$Support Glia: Astrocytes, Ependymal & Microglia$sub16$, $qt16$A neuropathologist examining infected brain tissue observes a CNS glial cell extending processes toward bacteria and a dying neuron, then engulfing and breaking down both. Which glial cell is the pathologist most likely observing?$qt16$, $op16$[{"label": "A", "text": "Astrocytes, which contribute to the blood-brain barrier and support neurons of the CNS"}, {"label": "B", "text": "Ependymal cells, which line the ventricles and produce the cerebrospinal fluid of the CNS"}, {"label": "C", "text": "Oligodendrocytes, which wrap and insulate the axons of CNS neurons in myelin"}, {"label": "D", "text": "Microglia, which serve as CNS-resident macrophages that ingest and digest pathogens and damaged cells"}]$op16$::jsonb, 'D', $ex16$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is D because microglia are the glial cells of the CNS that act as resident macrophages, ingesting and digesting pathogens and dead or damaged cells. OpenStax Anatomy & Physiology 2e states that when macrophages "encounter diseased or damaged cells... they ingest and digest those cells or the pathogens that cause disease. Microglia are the cells in the CNS that can do this... and they are therefore also referred to as CNS-resident macrophages." OpenStax Biology 2e similarly notes that "Microglia scavenge and degrade dead cells and protect the brain from invading microorganisms," which matches the immune-surveillance and phagocytosis role of engulfing both bacteria and a dying neuron. The other CNS glia each perform a distinct support function rather than phagocytic immune defense. (Choice A) Astrocytes are star-shaped supporting cells that maintain extracellular chemistry and contribute to the blood-brain barrier, not phagocytes. (Choice B) Ependymal cells line the ventricles and filter blood to make cerebrospinal fluid, a fluid-handling role rather than immune defense. (Choice C) Oligodendrocytes insulate CNS axons by wrapping them in myelin, an insulation role unrelated to ingesting pathogens. (Choice D) Microglia are the CNS-resident macrophages that ingest and digest pathogens and damaged cells, matching the observed behavior. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the defined immune-phagocytic function that distinguishes microglia from the other CNS glial cell types.$ex16$, 'easy', '3A', $cc16$Neuron & Glial Cell Structure$cc16$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a16A$Names a real CNS glial cell (astrocyte) but assigns its true support/blood-brain-barrier role instead of phagocytosis$a16A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a16B$Names a real CNS glial cell (ependymal) but assigns its true CSF-production role instead of phagocytosis$a16B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a16C$Names a real CNS glial cell (oligodendrocyte) but assigns its true myelination/insulation role instead of phagocytosis$a16C$ FROM q;

-- Q17 [Support Glia: Astrocytes, Ependymal & Microglia | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub17$Support Glia: Astrocytes, Ependymal & Microglia$sub17$, $qt17$A neuroscientist studying cerebrospinal fluid (CSF) production traces the fluid back to the glial cells that line the brain's ventricles and filter blood at the choroid plexus to generate it. The investigator needs to name the specific central nervous system glial cell responsible for producing this circulating fluid.$qt17$, $op17$[{"label": "A", "text": "Microglia, because they scavenge and degrade dead cells and pathogens within the central nervous system"}, {"label": "B", "text": "Astrocytes, because they regulate the extracellular chemical environment and help form the blood-brain barrier"}, {"label": "C", "text": "Ependymal cells, because they line the fluid-filled ventricles and filter blood to produce cerebrospinal fluid"}, {"label": "D", "text": "Oligodendrocytes, because they wrap axons in the myelin sheath that insulates them within the central nervous system"}]$op17$::jsonb, 'C', $ex17$This is a Biology question that falls under the content category 'Neuron & Glial Cell Structure'. The answer is C because ependymal cells are the central nervous system glial cell that lines the fluid-filled ventricles and filters blood at the choroid plexus to produce the cerebrospinal fluid that circulates through the CNS. OpenStax Anatomy & Physiology 2e states, "The ependymal cell is a glial cell that filters blood to make cerebrospinal fluid (CSF), the fluid that circulates through the CNS," and adds that "Ependymal cells line each ventricle." OpenStax Biology 2e likewise notes that "Ependymal cells line fluid-filled ventricles of the brain and the central canal of the spinal cord. They are involved in the production of cerebrospinal fluid." The other three glial types are real CNS cells but each performs a different role, so only the ependymal cell matches both the ventricular lining and the CSF-producing function described. (Choice A) Microglia are CNS-resident immune cells that "scavenge and degrade dead cells and protect the brain from invading microorganisms," an immune surveillance role rather than CSF production. (Choice B) Astrocytes are supporting cells that maintain "the concentration of chemicals in the extracellular space" and contribute "to the blood-brain barrier (BBB)," a support role rather than fluid production. (Choice C) Ependymal cells are correct because they line the ventricles and filter blood to make CSF, exactly the cell and function described in the scenario. (Choice D) Oligodendrocytes are "the glial cell type that insulates axons in the CNS" by forming myelin, a myelination role unrelated to CSF. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the defined function of a specific CNS glial cell directly from the textbook description.$ex17$, 'easy', '3A', $cc17$Neuron & Glial Cell Structure$cc17$, 'biology', 1, 75
  ) RETURNING id
)
